<?php declare(strict_types=1); namespace Annam;
$title='Orders';$subtitle=($total??count($records)).' orders';
$selected=$_GET['meal_group']??'all';$link=fn($group)=>'?'.http_build_query(array_replace($_GET,['meal_group'=>$group,'page'=>1]));
$groupLabel=fn($group)=>$group==='all'?'All orders':($group==='snacks'?'Snacks / Shop':implode(' + ',array_map('ucfirst',explode('+',$group))));
$combined=['breakfast+lunch'=>0];foreach($groups as $g=>$count)if(str_contains($g,'+'))$combined[$g]=$count;
?>
<nav class="order-groups" aria-label="Order food categories"><div class="order-group-row"><?php foreach(['all','breakfast','lunch','dinner','snacks'] as $g): ?><a class="o-btn <?= $selected===$g||($g==='all'&&!$selected)?'o-btn-primary':'' ?>" href="<?= e($link($g)) ?>" <?= $selected===$g?'aria-current="page"':'' ?>><?= e($groupLabel($g)) ?> <span class="order-group-count"><?= e($g==='all'?array_sum($groups):($groups[$g]??0)) ?></span></a><?php endforeach; ?></div><div class="order-group-row"><span class="order-group-caption">Combined orders</span><?php foreach($combined as $g=>$count): ?><a class="o-btn <?= $selected===$g?'o-btn-primary':'' ?>" href="<?= e($link($g)) ?>"><?= e($groupLabel($g)) ?> <span class="order-group-count"><?= e($count) ?></span></a><?php endforeach; ?></div></nav>
<p class="order-group-help"><?= e($groupLabel($selected?:'all')) ?> · Each row is one order. Combined orders keep one order number and one total.</p>
<form class="o-tools" method="get"><input type="hidden" name="meal_group" value="<?= e($selected) ?>"><label class="o-search"><svg class="o-ic"><use href="#o-search"/></svg><input type="search" name="q" value="<?= e($_GET['q']??'') ?>" placeholder="Order number, phone or name…" aria-label="Search orders"></label><label class="o-filter"><select class="o-input" name="status" aria-label="Status" data-autosubmit><option value="">All statuses</option><?php foreach(array_keys(Orders::FLOW) as $status): ?><option value="<?= e($status) ?>" <?= ($_GET['status']??'')===$status?'selected':'' ?>><?= e(ucfirst(str_replace('_',' ',$status))) ?></option><?php endforeach; ?></select></label><noscript><button class="o-btn">Search</button></noscript></form>
<?php if($records): ?><div class="o-table-wrap"><table class="o-table"><thead><tr><th>Order</th><th>Customer</th><th>For</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach($records as $record): ?><tr><td><a class="o-row-title" href="/manage/orders/<?= e($record['id']) ?>/"><?= e($record['order_no']) ?><?php if($record['test_payment']??false): ?> <span class="o-pill">TEST</span><?php endif; ?></a><small class="o-sub"><?= e(date('j M, g:i A',strtotime($record['placed_at']))) ?></small></td><td><?= e($record['customer_name']) ?><small class="o-sub"><?= e($record['customer_phone']) ?></small></td><td><strong class="order-meal-label"><?= e($record['meal_label']??'') ?></strong><?php if($record['delivery_date']): ?><small class="o-sub"><?= e(date('D, j M',strtotime($record['delivery_date']))) ?></small><?php endif; ?></td><td><span class="o-pill o-pill-<?= e($record['status']) ?>"><?= e(ucfirst(str_replace('_',' ',$record['status']))) ?></span></td><td class="o-money"><?= money($record['total']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php if($total>50): ?><nav class="o-pager" aria-label="Pages"><?php if($page>1): ?><a class="o-btn" href="?<?= e(http_build_query(array_replace($_GET,['page'=>$page-1]))) ?>">← Previous</a><?php endif; ?><span>Page <?= e($page) ?> of <?= e(ceil($total/50)) ?></span><?php if($page<ceil($total/50)): ?><a class="o-btn" href="?<?= e(http_build_query(array_replace($_GET,['page'=>$page+1]))) ?>">Next →</a><?php endif; ?></nav><?php endif; ?><?php else: ?><div class="o-empty"><svg class="o-ic"><use href="#o-bag"/></svg><p><?= !empty($_GET['q'])||!empty($_GET['status'])||!in_array($selected,['all',''],true)?'No orders match this food category and these filters.':'No orders yet. Website and WhatsApp orders will all appear here.' ?></p></div><?php endif; ?>
